#[cfg(target_os = "macos")]
fn install_macos_key_monitor<R: tauri::Runtime>(app: &tauri::App<R>) -> tauri::Result<()> {
    use block2::RcBlock;
    use objc2::rc::Retained;
    use objc2_app_kit::{NSEvent, NSEventMask};

    let app_handle = app.handle().clone();
    let block = RcBlock::new(move |event: Retained<NSEvent>| -> Option<Retained<NSEvent>> {
        let flags = event.modifierFlags();
        let chars = event.charactersIgnoringModifiers();
        let chars_str = chars.as_deref().map(|s| s.to_string());
        if is_unshifted_cmd_w(flags, chars_str.as_deref()) {
            if let Some(window) = app_handle.get_webview_window("main") {
                let _ = window.emit("menu_close_tab", ());
            }
            None
        } else {
            Some(event)
        }
    });

    let monitor = unsafe {
        NSEvent::addLocalMonitorForEventsMatchingMask_handler(
            NSEventMask::KeyDown,
            &block,
        )
    };
    if let Some(monitor) = monitor {
        let mut guard = MACOS_KEY_EVENT_MONITOR.lock();
        *guard = Some(monitor);
    }

    Ok(())
}

